namespace Atc.Rest.Api.SourceGenerator;

/// <summary>
/// Reports a <c>System.Enum</c> method called on a generated extensible enum (<c>ATC_API_CLT003</c>): the enum is a
/// struct, so <c>Enum.TryParse&lt;T&gt;</c>, <c>Enum.Parse&lt;T&gt;</c> and the <c>typeof</c> overloads
/// (<c>GetValues</c>, <c>IsDefined</c>, <c>GetNames</c>, ...) compile and throw an <c>ArgumentException</c> at run time.
/// The extensible enum is found by its shape: generated by this package, with <c>IsKnown</c> and <c>KnownValues</c>.
/// </summary>
[DiagnosticAnalyzer(LanguageNames.CSharp)]
public sealed class ExtensibleEnumUsageAnalyzer : DiagnosticAnalyzer
{
    private static readonly DiagnosticDescriptor Rule = new(
        RuleIdentifiers.SystemEnumOnExtensibleEnum,
        "System.Enum on an extensible enum",
        "'Enum.{0}' on '{1}' compiles and throws an ArgumentException at run time: '{1}' is an extensible enum (a struct), not a C# enum. {2}.",
        RuleIdentifiers.Category,
        DiagnosticSeverity.Warning,
        isEnabledByDefault: true,
        helpLinkUri: "https://github.com/atc-net/atc-rest-api-source-generator/wiki/Analyzer-Rules#atc_api_clt003");

    /// <inheritdoc />
    public override ImmutableArray<DiagnosticDescriptor> SupportedDiagnostics
        => [Rule];

    /// <inheritdoc />
    public override void Initialize(AnalysisContext context)
    {
        if (context is null)
        {
            throw new ArgumentNullException(nameof(context));
        }

        context.ConfigureGeneratedCodeAnalysis(GeneratedCodeAnalysisFlags.None);
        context.EnableConcurrentExecution();
        context.RegisterOperationAction(AnalyzeInvocation, OperationKind.Invocation);
    }

    private static void AnalyzeInvocation(OperationAnalysisContext context)
    {
        var invocation = (IInvocationOperation)context.Operation;
        var method = invocation.TargetMethod;
        if (method.ContainingType?.SpecialType != SpecialType.System_Enum)
        {
            return;
        }

        // Enum.TryParse<T>(...), Enum.Parse<T>(...): the type argument; Enum.GetValues(typeof(T)), ...: the type operand
        var type = method.TypeArguments.FirstOrDefault(IsExtensibleEnum) ??
                   invocation.Arguments
                       .Select(a => a.Value)
                       .OfType<ITypeOfOperation>()
                       .Select(t => t.TypeOperand)
                       .FirstOrDefault(IsExtensibleEnum);
        if (type is null)
        {
            return;
        }

        context.ReportDiagnostic(Diagnostic.Create(Rule, invocation.Syntax.GetLocation(), method.Name, type.Name, Advice(method.Name, type.Name)));
    }

    // What to write instead. A parse leads with the IsKnown check: the struct's own TryParse accepts every value (an
    // unlisted one too), so the one-word swap Enum.TryParse -> T.TryParse would drop a fallback for an unknown value
    private static string Advice(
        string methodName,
        string typeName)
        => methodName switch
        {
            "TryParse" or "Parse" => $"Keep a fallback for a value the specification does not list with IsKnown: new {typeName}(text) is {{ IsKnown: true }} value ? value : <fallback>. '{typeName}.TryParse' accepts every value, an unlisted one too",
            "IsDefined" => $"Use new {typeName}(text).IsKnown",
            "GetValues" or "GetValuesAsUnderlyingType" or "GetNames" or "GetName" => $"Use {typeName}.KnownValues (the listed values) or {typeName}.Names",
            _ => $"Use the struct's own members: {typeName}.KnownValues, {typeName}.Names, IsKnown or new {typeName}(...)",
        };

    private static bool IsExtensibleEnum(ITypeSymbol type)
        => type is INamedTypeSymbol { TypeKind: TypeKind.Struct } named &&
           named.GetMembers("IsKnown").OfType<IPropertySymbol>().Any(p => !p.IsStatic) &&
           named.GetMembers("KnownValues").Any(m => m.IsStatic) &&
           named.GetAttributes().Any(a =>
               a.AttributeClass?.Name == "GeneratedCodeAttribute" &&
               a.ConstructorArguments.Length > 0 &&
               a.ConstructorArguments[0].Value is string tool &&
               tool.StartsWith("Atc.Rest.Api", StringComparison.Ordinal));
}